def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    from collections import deque

    mod = 1_000_000_007
    size = len(alphabet)
    index = {ch: i for i, ch in enumerate(alphabet)}

    transitions = [[-1] * size]
    terminal = [False]

    for word in banned:
        state = 0
        for ch in word:
            c = index[ch]
            if transitions[state][c] == -1:
                transitions[state][c] = len(transitions)
                transitions.append([-1] * size)
                terminal.append(False)
            state = transitions[state][c]
        terminal[state] = True

    failure = [0] * len(transitions)
    queue = deque()

    for c in range(size):
        child = transitions[0][c]
        if child == -1:
            transitions[0][c] = 0
        else:
            queue.append(child)

    while queue:
        state = queue.popleft()
        terminal[state] |= terminal[failure[state]]

        for c in range(size):
            child = transitions[state][c]
            if child == -1:
                transitions[state][c] = transitions[failure[state]][c]
            else:
                failure[child] = transitions[failure[state]][c]
                queue.append(child)

    safe_states = [state for state in range(len(transitions)) if not terminal[state]]
    ids = {state: i for i, state in enumerate(safe_states)}
    count = len(safe_states)

    matrix = [[0] * count for _ in range(count)]
    for state in safe_states:
        row = matrix[ids[state]]
        for target in transitions[state]:
            if not terminal[target]:
                row[ids[target]] += 1

    vector = [0] * count
    vector[ids[0]] = 1

    while n:
        if n & 1:
            result = [0] * count
            for i, value in enumerate(vector):
                if value:
                    for j, weight in enumerate(matrix[i]):
                        result[j] += value * weight
            vector = [value % mod for value in result]

        n >>= 1
        if n:
            squared = [[0] * count for _ in range(count)]
            for i in range(count):
                for k, value in enumerate(matrix[i]):
                    if value:
                        for j, weight in enumerate(matrix[k]):
                            squared[i][j] += value * weight
                squared[i] = [value % mod for value in squared[i]]
            matrix = squared

    return sum(vector) % mod
